window.TADABBUR_FURQAN = {"_meta":{"description":"تدبّرٌ مُسنَد لسورة الفرقان (٢٥)، سورةٌ مكّيّةٌ محورُها تعظيمُ القرآنِ الفرقان، والردُّ على شبهاتِ المشركين في الرسولِ والبعثِ والتوحيد، وآياتُ القدرةِ في الكون، وصفاتُ عبادِ الرحمن. بُدئت بالحمد. كلُّ آيةٍ مغطّاةٍ تحمل وقفةً مُسنَدةً موسومة (ابن كثير/السعدي).","honesty":"لا نُقدّم شيئًا كإعجازٍ مُثبَت؛ المعنى منقولٌ بتصرّفٍ يسير من التفسيرين بإحالةٍ صريحة، والنصُّ القرآنيُّ يُؤخذ من المورفولوجيا وقتَ العرض."},"n":25,"name":"الفرقان","total_ayahs":77,"audio":[1,23,43,53,58,61,63,70,74,77],"passages":[{"title":"تبارك منزّلُ الفرقان","range":[1,3],"theme":"تعظيمُ منزّلِ القرآن، وملكُه وتنزيهُه، وبطلانُ عبادةِ العاجزين","verses":[{"n":1,"reflection":{"text":"«تبارك الذي نزل الفرقان على عبده ليكون للعالمين نذيرا» — تعاظم وكثر خيرُ الله الذي نزّل القرآنَ الفارقَ بين الحقِّ والباطلِ على عبده محمدٍ ﷺ ليكون منذرًا لجميعِ الخلق؛ ففي هذا تعظيمُ الله وبركتِه، وشرفُ القرآنِ وعمومُ رسالةِ النبيِّ ﷺ؛ فعظّم الله منزّلَ القرآن، واعرف قدرَ هذا الفرقانِ الذي أنذر به العالمين، واجعله فارقك بين الحقِّ والباطل.","source":"تفسير السعدي","grade":"ma'thur"},"names":["تبارك الذي نزل الفرقان","للعالمين نذيرا"],"heart_state":{"text":"تعظيمُ الله وقدرِ القرآنِ الفرقان."},"action":{"text":"عظّم الله الذي تبارك وكثر خيره، واعرف قدرَ القرآنِ الذي أنزله فرقانًا يفصل بين الحقِّ والباطل ونذيرًا للعالمين؛ فاجعله ميزانك الذي تزن به الأمور، وتلقَّه بالإجلالِ والعمل، فهو أعظمُ نعمةٍ أُنزِلت."}},{"n":2,"reflection":{"text":"«الذي له ملك السماوات والأرض ولم يتخذ ولدا ولم يكن له شريك في الملك وخلق كل شيء فقدره تقديرا» — الله الذي له وحده ملكُ السماواتِ والأرض، لم يتّخذ ولدًا ولا شريكًا في الملك، وخلق كلَّ شيءٍ فقدّره تقديرًا محكمًا بحكمته؛ ففي هذا إثباتُ كمالِ ملكِ الله وتنزيهِه عن الولدِ والشريك، وإحكامِ خلقه وتقديره؛ فوحّد الله ونزّهه، وتأمّل إحكامَ تقديره في خلقه، فكلُّ شيءٍ مقدَّرٌ بحكمة، فسلّم لقدره وأحسن الظنَّ بتدبيره.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["له ملك السماوات والأرض","خلق كل شيء فقدره تقديرا"],"heart_state":{"text":"توحيدُ الله وتنزيهُه، والتسليمُ لإحكامِ تقديره."},"action":{"text":"وحّد الله في ملكه ونزّهه عن الولدِ والشريك، وتأمّل إحكامَ خلقه وتقديره لكلِّ شيءٍ بحكمة؛ فسلّم لقدره وأحسن الظنَّ بتدبيره، فما خلق شيئًا إلا بمقدارٍ وحكمةٍ بالغة، فاعبده وحده وارضَ بقضائه."}},{"n":3,"reflection":{"text":"«واتخذوا من دونه آلهة لا يخلقون شيئا وهم يخلقون ولا يملكون لأنفسهم ضرا ولا نفعا ولا يملكون موتا ولا حياة ولا نشورا» — واتّخذ المشركون من دون الله آلهةً لا تخلق شيئًا بل هي مخلوقة، ولا تملك لأنفسها ضرًّا ولا نفعًا، ولا تملك موتًا ولا حياةً ولا بعثًا؛ ففي هذا إبطالُ عبادةِ ما لا يخلق ولا ينفع ولا يضرّ، وأنّ المعبودَ الحقَّ من يملك ذلك؛ فلا تعبد إلا من يخلق ويملك النفعَ والضرَّ والحياةَ والموتَ والبعث، وهو الله وحده، فما سواه عاجزٌ لا يستحقّ العبادة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["لا يخلقون شيئا وهم يخلقون"],"heart_state":{"text":"إفرادُ الله بالعبادةِ لعجزِ كلِّ ما سواه."},"action":{"text":"لا تعبد ولا ترجُ ولا تخف إلا الله الذي يخلق ويملك النفعَ والضرَّ والحياةَ والموتَ والبعث؛ فكلُّ ما سواه مخلوقٌ عاجزٌ لا يملك لنفسه شيئًا فضلًا عن غيره؛ فأخلص عبادتك للخالقِ القادرِ وحده، فذلك مقتضى العقلِ والفطرة."}}]},{"title":"شبهاتُ المشركين في القرآنِ والرسول","range":[4,9],"theme":"طعنُهم في القرآنِ بالافتراء، وفي الرسولِ ببشريّته، والردُّ عليهم","verses":[{"n":4,"reflection":{"text":"«وقال الذين كفروا إن هذا إلا إفك افتراه وأعانه عليه قوم آخرون فقد جاءوا ظلما وزورا» — وقال الكفار: ما هذا القرآنُ إلا كذبٌ اختلقه محمدٌ وأعانه عليه قومٌ آخرون (من أهلِ الكتاب)، فقد جاؤوا بظلمٍ عظيمٍ وكذبٍ بيّن؛ ففي هذا افتراءُ المشركين على القرآنِ ورميُهم له بالكذب، وأنّ ذلك ظلمٌ وزور؛ فلا يهزّك طعنُ الطاعنين في القرآن، فطعنهم ظلمٌ وزورٌ لا حجّةَ فيه، والزم اليقينَ بأنه كلامُ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على أنّ القرآنَ كلامُ الله رغمَ طعنِ الطاعنين."},"action":{"text":"لا يزعزعك طعنُ الطاعنين في القرآنِ ورميُهم له بالافتراء، فطعنهم ظلمٌ وزورٌ لا برهانَ فيه؛ فالزم اليقينَ بأنه كلامُ الله المعجز، وازدد به تمسّكًا وتعظيمًا، فالباطلُ لا يقدح في الحقِّ الثابت."}},{"n":5,"reflection":{"text":"«وقالوا أساطير الأولين اكتتبها فهي تملى عليه بكرة وأصيلا» — وقالوا: القرآنُ أكاذيبُ الأوّلين وخرافاتهم كتبها محمدٌ لنفسه فهي تُقرأ عليه صباحًا ومساءً ليحفظها؛ ففي هذا تناقضُ المشركين (مرّةً افتراء، ومرّةً أساطير مكتوبة)، وأنّ المعاندَ يتخبّط في ردِّ الحقّ؛ فتأمّل تناقضَ المبطلين دليلًا على بطلانهم، ولا تُصغِ لطعنهم في كتابِ الله، فالحقُّ واحدٌ والباطلُ متناقض.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بتناقضِ المبطلين وعدمُ الإصغاءِ لطعنهم."},"action":{"text":"تأمّل كيف يتناقض المبطلون في طعنهم (افتراءً تارةً وأساطيرَ تارةً)، فذلك دليلُ بطلانهم؛ ولا تُصغِ لطعنهم في كتابِ الله، والزم الحقَّ الواحدَ الثابت؛ فالباطلُ شعبٌ متناقضة، والحقُّ نورٌ واحدٌ لا اضطرابَ فيه."}},{"n":6,"reflection":{"text":"«قل أنزله الذي يعلم السر في السماوات والأرض إنه كان غفورا رحيما» — قل لهم: أنزل هذا القرآنَ الذي يعلم السرَّ في السماواتِ والأرض، فمن هذا شأنه لا يخفى عليه شيءٌ فكيف يُفترى عليه؟ إنه كان غفورًا رحيمًا يدعو المكذّبين إلى التوبة؛ ففي هذا إثباتُ أنّ القرآنَ من عند العالمِ بالسرّ، وفتحُ بابِ الرحمةِ للمكذّبين إن تابوا؛ فاعلم أنّ القرآنَ من عند عالمِ الغيب، وارجُ مغفرةَ الله ورحمته، فبابُ التوبةِ مفتوحٌ حتى للمعاندين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["يعلم السر في السماوات والأرض","غفورا رحيما"],"heart_state":{"text":"اليقينُ بأنّ القرآنَ من عالمِ السرّ، ورجاءُ مغفرته."},"action":{"text":"أيقن بأنّ القرآنَ من عند الله العالمِ بالسرِّ في السماواتِ والأرض، فلا يخفى عليه شيء؛ وارجُ مغفرته ورحمته وتب إليه، فهو غفورٌ رحيمٌ يفتح بابَ التوبةِ حتى للمعاندين؛ فبادر بالرجوعِ إليه قبل الفوات."}},{"n":7,"reflection":{"text":"«وقالوا مال هذا الرسول يأكل الطعام ويمشي في الأسواق لولا أنزل إليه ملك فيكون معه نذيرا» — وقالوا مستنكرين: ما لهذا الرسولِ يأكل الطعامَ ويمشي في الأسواقِ كسائرِ الناس؟ هلّا أُنزِل معه ملَكٌ يصدّقه ويشاركه الإنذار؟ ففي هذا طعنُ المشركين في الرسولِ ببشريّته، وأنّ الكِبرَ يحملهم على اقتراحِ الآيات؛ فلا تستنكر بشريّةَ الرسل، فهي رحمةٌ ليتأسّى بهم الناس، ولا تعلّق الإيمانَ باقتراحاتٍ باطلة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ بشريّةِ الرسلِ وعدمُ تعليقِ الإيمانِ بالاقتراحات."},"action":{"text":"لا تستنكر بشريّةَ الرسلِ في أكلهم ومشيهم بين الناس، فتلك رحمةٌ ليكونوا قدوةً يُتأسّى بها؛ ولا تعلّق إيمانك أو قبولك للحقِّ باقتراحاتٍ باطلةٍ كطلبِ نزولِ ملَك؛ فالعبرةُ بصدقِ ما جاء به الرسولُ لا بمفارقتِه طبعَ البشر."}},{"n":8,"reflection":{"text":"«أو يلقى إليه كنز أو تكون له جنة يأكل منها وقال الظالمون إن تتبعون إلا رجلا مسحورا» — أو هلّا أُلقِي إليه كنزٌ يستغني به، أو تكون له حديقةٌ يأكل منها، وقال الظالمون للمؤمنين: ما تتّبعون إلا رجلًا مسحورًا زال عقله؛ ففي هذا اقتراحُهم للآياتِ الدنيويّةِ وطعنهم في عقلِ الرسول، وأنّ الكِبرَ يعمي عن الحقّ؛ فلا يهزّك اتّهامُ المبطلين لأهلِ الحقِّ بالسحرِ والجنون، فتلك سنّةُ المكذّبين، والعاقبةُ للصادقين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ رغمَ اتّهامِ المبطلين لأهلِ الحقّ."},"action":{"text":"لا يزعزعك اتّهامُ المبطلين لأهلِ الحقِّ بالسحرِ أو الجنونِ أو غيرها من الباطل، فتلك حيلةُ العاجزِ عن الحجّة وسنّةُ المكذّبين مع الرسل؛ فامضِ في الحقِّ واثقًا بصدقه، فالعاقبةُ للصادقين لا للطاعنين."}},{"n":9,"reflection":{"text":"«انظر كيف ضربوا لك الأمثال فضلوا فلا يستطيعون سبيلا» — انظر يا محمد كيف وصفوك بالأوصافِ الباطلةِ (ساحرٌ، مجنون، مفترٍ) فضلّوا عن الحقِّ فلا يجدون سبيلًا إلى الطعنِ الصحيحِ ولا إلى الهدى؛ ففي هذا أنّ المبطلَ يتخبّط في الأمثالِ الباطلةِ فيضلّ، وأنّ العاجزَ عن الحقِّ لا يجد مخرجًا؛ فلا تبالِ بأمثالِ المبطلين وأوصافهم الباطلة، فهم ضالّون حائرون، والزم الحقَّ الذي لا يعجزك سبيله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ المبالاةِ بأمثالِ المبطلين الباطلةِ ولزومُ الحقّ."},"action":{"text":"لا تبالِ بما يصفك به المبطلون من أوصافٍ باطلةٍ متناقضة، فهم ضالّون حائرون لا يجدون للطعنِ سبيلًا ولا للهدى طريقًا؛ فالزم الحقَّ الواضحَ الذي أنت عليه، ولا تشغل قلبك بترّهاتهم، فالعاقبةُ للحقِّ وأهله."}}]},{"title":"تكذيبُهم بالساعةِ وعذابُ السعير","range":[10,14],"theme":"فضلُ الله على نبيّه، وتكذيبُ المشركين بالبعث، وأهوالُ النار","verses":[{"n":10,"reflection":{"text":"«تبارك الذي إن شاء جعل لك خيرا من ذلك جنات تجري من تحتها الأنهار ويجعل لك قصورا» — تعاظم الله الذي إن شاء جعل لك يا محمد خيرًا ممّا اقترحوه: جناتٍ تجري من تحتها الأنهار، ويجعل لك قصورًا في الدنيا؛ ففي هذا أنّ العطاءَ كلَّه بيدِ الله يعطيه من يشاء، وأنّ منزلةَ النبيِّ ﷺ لا تُقاس بمتاعِ الدنيا؛ فاعلم أنّ الخيرَ كلَّه بيدِ الله، ولا تقس منازلَ الناسِ عند الله بما أُوتوا من دنيا، فالكرامةُ بالإيمانِ لا بالمال.","source":"تفسير السعدي","grade":"ma'thur"},"names":["تبارك الذي إن شاء جعل لك خيرا من ذلك"],"heart_state":{"text":"العلمُ بأنّ العطاءَ بيدِ الله، وعدمُ قياسِ المنازلِ بالدنيا."},"action":{"text":"اعلم أنّ الخيرَ والعطاءَ كلَّه بيدِ الله يؤتيه من يشاء، ولا تقس منزلةَ العبدِ عند الله بما أُوتي من دنيا؛ فالكرامةُ بالإيمانِ والتقوى لا بالمالِ والقصور؛ فاطلب الغنى الحقيقيَّ وهو غنى القلبِ ورضا الله."}},{"n":11,"reflection":{"text":"«بل كذبوا بالساعة وأعتدنا لمن كذب بالساعة سعيرا» — بل حقيقةُ أمرهم أنهم كذّبوا بالقيامة، وأعتدنا لمن كذّب بالساعةِ نارًا مستعرة؛ ففي هذا أنّ أصلَ ضلالهم تكذيبُ البعث، وأنّ جزاءَ المكذّبِ به السعير؛ فأيقن بالساعةِ واعمل لها، واحذر التكذيبَ بها، فإنه سببُ العذاب، فمن أنكر البعثَ تجرّأ على المعاصي.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالساعةِ والحذرُ من التكذيبِ بها."},"action":{"text":"أيقن بالساعةِ والبعثِ واعمل لهما، واحذر التكذيبَ بهما فإنه أصلُ الضلالِ وسببُ العذابِ في السعير؛ فمن أنكر البعثَ تجرّأ على المعاصي، ومن أيقن به استعدَّ له بالطاعةِ وترْكِ الحرام."}},{"n":12,"reflection":{"text":"«إذا رأتهم من مكان بعيد سمعوا لها تغيظا وزفيرا» — إذا رأتهم النارُ من مكانٍ بعيدٍ سمعوا لها صوتَ الغيظِ والغليانِ والزفيرِ الشديد؛ ففي هذا تصويرُ هولِ النارِ وشدّةِ غضبها على أهلها، وأنها كالحيِّ الغاضب؛ فاحذر النارَ التي هذا حالها، واعمل على النجاةِ منها بالإيمانِ والطاعة، فهولها يفوق الوصف.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من هولِ النارِ والعملُ للنجاة."},"action":{"text":"احذر النارَ التي تتغيّظ على أهلها ويُسمَع زفيرها من بعيد، واعمل على النجاةِ منها بالإيمانِ والطاعةِ وترْكِ ما يوردها؛ فمن استحضر هولها وشدّةَ غضبها جدَّ في اجتنابِ أسبابها من الكفرِ والمعاصي."}},{"n":13,"reflection":{"text":"«وإذا ألقوا منها مكانا ضيقا مقرنين دعوا هنالك ثبورا» — وإذا أُلقِي المكذّبون في مكانٍ ضيّقٍ من النارِ مقيّدين بالسلاسلِ دعوا على أنفسهم بالهلاكِ والويل؛ ففي هذا تصويرُ ضيقِ النارِ وإهانةِ أهلها بالتقييد، وأنهم يتمنّون الهلاك؛ فاحذر مصيرًا يُتمنّى فيه الهلاك، واعمل لسعةِ الجنّةِ ونعيمها، فبين المصيرين بونٌ بعيد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عذابِ النارِ الضيّقِ والعملُ للنعيم."},"action":{"text":"احذر أن تكون من أهلِ نارٍ يُلقَون في مكانٍ ضيّقٍ مقيّدين فيدعون بالهلاك، واعمل لسعةِ الجنّةِ ونعيمها بالإيمانِ والطاعة؛ فوازِن بين ضيقِ النارِ وسعةِ الجنّةِ لتؤثر دارَ النعيم."}},{"n":14,"reflection":{"text":"«لا تدعوا اليوم ثبورا واحدا وادعوا ثبورا كثيرا» — يقال لهم: لا تدعوا اليومَ بالهلاكِ مرّةً واحدة، بل ادعوا بهلاكٍ كثيرٍ لدوامِ عذابكم؛ ففي هذا زيادةٌ في إهانتهم وبيانُ دوامِ عذابهم الذي لا ينقطع؛ فاحذر عذابًا لا ينفع فيه دعاءٌ ولا يُقطَع بهلاك، واعمل على النجاةِ منه في دارِ العمل، فالفرصةُ الآن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من العذابِ الدائمِ والعملُ للنجاةِ منه."},"action":{"text":"احذر عذابَ النارِ الدائمَ الذي لا ينقطع بهلاكٍ ولا ينفع فيه دعاء، واعمل على النجاةِ منه بالإيمانِ والطاعةِ ما دمت في مهلةِ الحياة؛ فالفرصةُ الآن للعمل، وبعد الموتِ لا تدارك، فبادر قبل الفوات."}}]},{"title":"جنّةُ الخلد، وتبرّؤُ المعبودات","range":[15,19],"theme":"مقارنةُ النارِ بالجنّة، وتبرّؤُ المعبوداتِ من عابديها يوم القيامة","verses":[{"n":15,"reflection":{"text":"«قل أذلك خير أم جنة الخلد التي وعد المتقون كانت لهم جزاء ومصيرا» — قل: أذلك العذابُ خيرٌ أم جنةُ الخلدِ التي وعدها الله المتّقين، كانت لهم جزاءً على أعمالهم ومصيرًا يصيرون إليه؟ ففي هذا موازنةٌ بين مصيرِ الفريقين لتُؤثَر الجنّة، وأنّ الجنّةَ جزاءُ التقوى؛ فوازِن بين النارِ وجنّةِ الخلد، واعمل بالتقوى لتكون من أهلِ الجنّة، فالعاقلُ يؤثر الباقيةَ الطيّبة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["جنة الخلد التي وعد المتقون"],"heart_state":{"text":"الموازنةُ بين المصيرين والعملُ بالتقوى للجنّة."},"action":{"text":"وازِن بين عذابِ النارِ ونعيمِ جنّةِ الخلد، واعمل بالتقوى لتكون من أهلِ الجنّةِ التي وعدها الله المتّقين؛ فالعاقلُ يؤثر الدارَ الباقيةَ الطيّبةَ على متاعٍ زائل، فاجعل التقوى زادك إليها."}},{"n":16,"reflection":{"text":"«لهم فيها ما يشاءون خالدين كان على ربك وعدا مسئولا» — لأهلِ الجنّةِ فيها كلُّ ما يشتهون خالدين أبدًا، كان ذلك على ربّك وعدًا مسؤولًا يسأله المؤمنون ويحقّقه لهم؛ ففي هذا كمالُ نعيمِ الجنّةِ ودوامِه، وأنّ وعدَ الله محقّقٌ لا يتخلّف؛ فاعمل لجنّةٍ فيها ما تشتهي النفوسُ خالدةً، واسأل الله الجنّةَ فوعده حقٌّ مسؤول، فارجُ منه ما وعد به عباده.","source":"تفسير السعدي","grade":"ma'thur"},"names":["لهم فيها ما يشاءون خالدين","وعدا مسئولا"],"heart_state":{"text":"العملُ للجنّةِ ذاتِ النعيمِ الدائم، وسؤالُها من الله."},"action":{"text":"اعمل لجنّةٍ فيها ما تشتهي الأنفسُ من النعيمِ الدائمِ الخالد، واسأل الله الجنّةَ فوعده بها حقٌّ مسؤولٌ لا يتخلّف؛ فارجُ منه ما وعد به عباده المتّقين، واجعل نعيمها المقيمَ غايةَ سعيك ومطلبك."}},{"n":17,"reflection":{"text":"«ويوم يحشرهم وما يعبدون من دون الله فيقول أأنتم أضللتم عبادي هؤلاء أم هم ضلوا السبيل» — ويوم يجمع الله المشركين ومعبوداتهم، فيقول للمعبودات: أأنتم أضللتم عبادي هؤلاء أم هم ضلّوا الطريقَ بأنفسهم؟ ففي هذا فضحُ الشركِ يوم القيامة، وأنّ المعبوداتِ تُسأَل وتتبرّأ؛ فتأمّل خزيَ الشركِ يوم القيامة، وأخلص عبادتك لله وحده، فكلُّ معبودٍ سواه يتبرّأ من عابده يومئذ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ خزيِ الشركِ يومَ القيامة، وإخلاصُ العبادة."},"action":{"text":"استحضر خزيَ الشركِ وفضيحتَه يوم القيامةِ حين تُسأَل المعبوداتُ فتتبرّأ من عابديها، وأخلص عبادتك لله وحده؛ فلا تعلّق قلبك بمعبودٍ أو مخلوقٍ يتبرّأ منك أحوجَ ما تكون إليه، فالنجاةُ في التوحيد."}},{"n":18,"reflection":{"text":"«قالوا سبحانك ما كان ينبغي لنا أن نتخذ من دونك من أولياء ولكن متعتهم وآباءهم حتى نسوا الذكر وكانوا قوما بورا» — قالت المعبوداتُ: تنزّهت يا ربّنا، ما كان يليق بنا أن نتّخذ من دونك أولياءَ فكيف نأمر بعبادتنا؟ ولكنك متّعتهم وآباءهم بالنعمِ حتى نسوا ذكرك واستدرجهم ذلك، وكانوا قومًا هالكين؛ ففي هذا أنّ التمتّعَ بالنعمِ قد يُنسي ذكرَ الله ويؤدّي إلى الهلاك؛ فاحذر أن تُنسيك النعمةُ ذكرَ الله، فنسيانُ الذكرِ سببُ الهلاك، فاشكر النعمةَ بالطاعة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["حتى نسوا الذكر وكانوا قوما بورا"],"heart_state":{"text":"الحذرُ من أن تُنسي النعمةُ ذكرَ الله."},"action":{"text":"احذر أن يُنسيك التمتّعُ بالنعمِ ذكرَ الله وشكرَه، فنسيانُ الذكرِ بسببِ الاستغراقِ في الملذّاتِ سببُ الهلاك؛ فاشكر نعمَ الله بطاعته وذكره، ولا تدعها تشغلك عنه، فالغافلُ عن ذكرِ الله في خطرِ البوارِ والهلاك."}},{"n":19,"reflection":{"text":"«فقد كذبوكم بما تقولون فما تستطيعون صرفا ولا نصرا ومن يظلم منكم نذقه عذابا كبيرا» — يقال للمشركين: فقد كذّبكم معبودوكم بما كنتم تقولون من أنهم آلهة، فما تستطيعون دفعَ العذابِ عن أنفسكم ولا نصرَها، ومن يظلم منكم بالشركِ نذقه عذابًا كبيرًا؛ ففي هذا خذلانُ المعبوداتِ لعابديها، وأنّ الظلمَ (الشرك) موجبٌ للعذاب؛ فلا تتّكل على من يخذلك يوم حاجتك، وأخلص لله، واحذر الظلمَ فإنه سببُ العذابِ الكبير.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاتّكالِ على من يخذل، والحذرُ من الظلم."},"action":{"text":"لا تتّكل على معبودٍ أو مخلوقٍ يخذلك يوم القيامةِ ويتبرّأ منك، بل أخلص لله وحده؛ واحذر الظلمَ وأعظمَه الشرك، فمن ظلم أُذيق عذابًا كبيرًا؛ فالزم التوحيدَ والعدل، فبهما النجاةُ من العذاب."}}]},{"title":"سنّةُ الله في الرسلِ والابتلاء","range":[20,20],"theme":"أنّ الرسلَ بشرٌ يأكلون، وأنّ الناسَ فتنةٌ بعضهم لبعض","verses":[{"n":20,"reflection":{"text":"«وما أرسلنا قبلك من المرسلين إلا إنهم ليأكلون الطعام ويمشون في الأسواق وجعلنا بعضكم لبعض فتنة أتصبرون وكان ربك بصيرا» — وما أرسلنا قبلك رسلًا إلا وهم يأكلون الطعامَ ويمشون في الأسواقِ كسائرِ البشر، وجعلنا بعضكم لبعضٍ ابتلاءً (الغنيَّ بالفقيرِ والصحيحَ بالمريضِ والرسولَ بالمكذّب) أتصبرون على ذلك؟ وكان ربّك بصيرًا بمن يصبر؛ ففي هذا أنّ بشريّةَ الرسلِ سنّةٌ ماضية، وأنّ الناسَ يُبتلى بعضهم ببعضٍ ليُعرَف الصابر؛ فاصبر على ما ابتلاك الله به من أحوالِ الناس، واعلم أنّ الله بصيرٌ بصبرك يجازيك عليه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["وجعلنا بعضكم لبعض فتنة أتصبرون","وكان ربك بصيرا"],"heart_state":{"text":"الصبرُ على ابتلاءِ الناسِ بعضهم ببعض."},"action":{"text":"اصبر على ما يبتليك الله به من أحوالِ الناسِ حولك ــ غنيٍّ وفقيرٍ ومطيعٍ وعاصٍ ــ فبعضهم فتنةٌ لبعضٍ يُختبَر بها الصبر؛ واعلم أنّ الله بصيرٌ بصبرك يجازيك عليه؛ فوطّن نفسك على الصبر، فهو مفتاحُ النجاةِ والأجر."}}]},{"title":"استكبارُهم وحبوطُ أعمالهم","range":[21,24],"theme":"طلبُهم رؤيةَ الملائكةِ والربّ، وبطلانُ أعمالِ الكفار، وخيريّةُ أهلِ الجنّة","verses":[{"n":21,"reflection":{"text":"«وقال الذين لا يرجون لقاءنا لولا أنزل علينا الملائكة أو نرى ربنا لقد استكبروا في أنفسهم وعتوا عتوا كبيرا» — وقال الذين لا يخافون البعثَ ولا يرجون ثوابنا: هلّا أُنزِلت علينا الملائكةُ نراها، أو نرى ربّنا عِيانًا فيخبرنا بصدقِ محمد؟ لقد تعاظموا في أنفسهم وتجاوزوا الحدَّ في العنادِ والكفر؛ ففي هذا أنّ الكِبرَ يحمل على اقتراحِ المحالِ وردِّ الحقّ، وأنّ العتوَّ يُعمي؛ فاحذر الكِبرَ الذي يحملك على ردِّ الحقِّ واقتراحِ ما لا يليق، والزم التواضعَ للحقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكِبرِ الحاملِ على ردِّ الحقّ."},"action":{"text":"احذر الكِبرَ والعتوَّ الذي يحمل صاحبه على ردِّ الحقِّ واقتراحِ المحال، كما فعل هؤلاء؛ والزم التواضعَ للحقِّ وقبوله ممّن جاء به؛ فالمتكبّرُ يُحرَم الهدى، والمتواضعُ يُفتَح له بابُ القبول، فذلّل نفسك للحقّ."}},{"n":22,"reflection":{"text":"«يوم يرون الملائكة لا بشرى يومئذ للمجرمين ويقولون حجرا محجورا» — يوم يرون الملائكةَ (عند الموتِ والقيامة) لا بشرى لهم بخيرٍ يومئذ، وتقول لهم الملائكةُ: حرامًا محرّمًا عليكم البشرى والجنّة؛ ففي هذا أنّ رؤيةَ الملائكةِ التي طلبوها تكون عذابًا لا بشرى، وأنّ المجرمَ محرومٌ من البشرى؛ فاعمل لتكون من أهلِ البشرى عند لقاءِ الملائكة، فالبشرى للمؤمنين والحرمانُ للمجرمين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لتكون من أهلِ البشرى عند لقاءِ الملائكة."},"action":{"text":"اعمل بالإيمانِ والطاعةِ لتكون من أهلِ البشرى الذين تتلقّاهم الملائكةُ بالخيرِ عند الموتِ والقيامة؛ فالمجرمون يرون الملائكةَ فلا بشرى لهم بل حرمان؛ فاجتهد أن تُبشَّر لا أن تُحرَم، بتقوى الله وصالحِ العمل."}},{"n":23,"reflection":{"text":"«وقدمنا إلى ما عملوا من عمل فجعلناه هباء منثورا» — وعمدنا إلى ما عمله الكفارُ من أعمالٍ ظنّوها خيرًا (كصلةِ الرحمِ والصدقةِ بلا إيمان) فجعلناها كالغبارِ المتفرّقِ الذي لا ينتفع به؛ ففي هذا أنّ أعمالَ الكفارِ تحبط لفقدِ الإيمان، وأنّ العملَ بلا إيمانٍ هباء؛ فاحرص على أن يكون عملك مبنيًّا على الإيمانِ والإخلاصِ ليُقبَل، فالعملُ بلا إيمانٍ أو إخلاصٍ يصير هباءً منثورًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":["فجعلناه هباء منثورا"],"heart_state":{"text":"الحرصُ على بناءِ العملِ على الإيمانِ والإخلاص."},"action":{"text":"احرص على أن يكون عملك مبنيًّا على الإيمانِ الصحيحِ والإخلاصِ لله، لئلا يصير هباءً منثورًا كأعمالِ الكفارِ التي حبطت لفقدِ الإيمان؛ فحقّق الإيمانَ أوّلًا، وأخلص العملَ لله، فبهما يُقبَل ويثقل في الميزان."}},{"n":24,"reflection":{"text":"«أصحاب الجنة يومئذ خير مستقرا وأحسن مقيلا» — أهلُ الجنّةِ يومئذٍ خيرٌ مستقرًّا وأحسنُ مكانًا للقيلولةِ والراحةِ من أهلِ النار؛ ففي هذا بيانُ خيريّةِ منزلِ أهلِ الجنّةِ مقابلَ ضيقِ النار، وأنّ راحةَ أهلِ الجنّةِ تفوق الوصف؛ فاعمل لتكون من أصحابِ الجنّةِ الذين لهم خيرُ مستقرٍّ وأحسنُ مقيل، فراحتهم دائمةٌ ونعيمهم مقيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لتكون من أصحابِ الجنّةِ ذوي المستقرِّ الحسن."},"action":{"text":"اعمل بالإيمانِ والطاعةِ لتكون من أصحابِ الجنّةِ الذين لهم خيرُ مستقرٍّ وأحسنُ مقيلٍ وراحة، مقابلَ ضيقِ أهلِ النارِ وعذابهم؛ فوازِن بين المصيرين، واجعل همّك دارَ النعيمِ التي راحتها دائمةٌ ونعيمها مقيم."}}]},{"title":"يومُ تشقّقِ السماءِ وندمُ الظالم","range":[25,29],"theme":"مشهدُ القيامة، وأنّ الملكَ للرحمن، وندمُ من اتّبع خليلَ السوء","verses":[{"n":25,"reflection":{"text":"«ويوم تشقق السماء بالغمام ونزل الملائكة تنزيلا» — واذكر يوم تتشقّق السماءُ عن غمامٍ أبيضَ رقيق، وينزل الملائكةُ تنزيلًا كثيرًا يحيطون بالخلائق؛ ففي هذا تصويرُ هولِ يومِ القيامةِ وعظمتِه بتشقّقِ السماءِ ونزولِ الملائكة؛ فاستحضر هولَ ذلك اليومِ العظيم، واستعدَّ له بالعملِ الصالح، فمن استعظم هوله جدَّ في الاستعداد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ هولِ يومِ القيامةِ والاستعدادُ له."},"action":{"text":"استحضر هولَ يومِ القيامةِ حين تتشقّق السماءُ وينزل الملائكةُ محيطين بالخلائق، واستعدَّ لذلك اليومِ العظيمِ بالإيمانِ والعملِ الصالح؛ فمن استعظم هوله في قلبه جدَّ في العملِ له ولم يغترّ بالدنيا."}},{"n":26,"reflection":{"text":"«الملك يومئذ الحق للرحمن وكان يوما على الكافرين عسيرا» — الملكُ الحقُّ الثابتُ يومئذٍ للرحمنِ وحده لا يدّعيه أحدٌ سواه، وكان ذلك اليومُ على الكافرين شديدًا عسيرًا؛ ففي هذا انفرادُ الرحمنِ بالملكِ يوم القيامة، وأنّ ذلك اليومَ عسيرٌ على الكافرين يسيرٌ على المؤمنين؛ فاعمل ليكون ذلك اليومُ يسيرًا عليك، فالملكُ يومئذٍ للرحمن، فاطلب رحمته بالإيمانِ والطاعة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الملك يومئذ الحق للرحمن"],"heart_state":{"text":"العملُ ليكون يومُ القيامةِ يسيرًا برحمةِ الله."},"action":{"text":"اعمل بالإيمانِ والطاعةِ لتكون من المؤمنين الذين ييسّر الله عليهم يومَ القيامة، لا من الكافرين الذين هو عليهم عسير؛ فالملكُ يومئذٍ للرحمنِ وحده، فاطلب رحمته والزم طاعته، فمن رحمه الله هان عليه ذلك اليوم."}},{"n":27,"reflection":{"text":"«ويوم يعض الظالم على يديه يقول يا ليتني اتخذت مع الرسول سبيلا» — ويوم يعضّ الظالمُ (المشركُ) على يديه ندمًا وحسرةً يقول: يا ليتني اتّخذت مع الرسولِ طريقًا إلى الهدى؛ ففي هذا ندمُ الظالمِ يوم القيامةِ على ترْكِ اتّباعِ الرسول، وأنّ الندمَ حينئذٍ لا ينفع؛ فاتّبع الرسولَ اليومَ والزم سبيله، قبل يومٍ يعضّ فيه المفرّطُ على يديه ندمًا حيث لا ينفع الندم.","source":"تفسير السعدي","grade":"ma'thur"},"names":["يا ليتني اتخذت مع الرسول سبيلا"],"heart_state":{"text":"اتّباعُ الرسولِ اليومَ قبل يومِ الندمِ الذي لا ينفع."},"action":{"text":"اتّبع الرسولَ ﷺ والزم سبيله وسنّته اليومَ في مهلةِ الحياة، قبل يومٍ يعضّ فيه المفرّطُ على يديه متمنّيًا لو اتّبعه؛ فالندمُ يوم القيامةِ لا يجدي، فبادر باتّباعِ الهدى قبل فواتِ الأوان."}},{"n":28,"reflection":{"text":"«يا ويلتى ليتني لم أتخذ فلانا خليلا» — يقول الظالم متحسّرًا: يا هلاكي ليتني لم أتّخذ فلانًا (خليلَ السوءِ الذي أضلّني) صديقًا؛ ففي هذا أنّ خليلَ السوءِ سببُ الندمِ والهلاك، وأنّ الصحبةَ السيّئةَ تجرّ إلى النار؛ فاختر خليلك على الخيرِ والدين، واحذر أخلّاءَ السوءِ الذين يصدّونك عن الحقّ، فالمرءُ على دينِ خليله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["ليتني لم أتخذ فلانا خليلا"],"heart_state":{"text":"اختيارُ الخليلِ الصالحِ والحذرُ من خليلِ السوء."},"action":{"text":"اختر أخلّاءك وأصدقاءك من أهلِ الخيرِ والدينِ الذين يعينونك على الطاعة، واحذر خليلَ السوءِ الذي يصدّك عن الحقِّ ويجرّك إلى الباطل؛ فالمرءُ على دينِ خليله، وخليلُ السوءِ سببُ الندمِ يوم القيامة."}},{"n":29,"reflection":{"text":"«لقد أضلني عن الذكر بعد إذ جاءني وكان الشيطان للإنسان خذولا» — يقول: لقد صرفني خليلُ السوءِ عن القرآنِ والحقِّ بعد أن جاءني، وكان الشيطانُ للإنسانِ كثيرَ الخذلانِ يتركه عند الشدّة؛ ففي هذا أنّ خليلَ السوءِ والشيطانَ يخذلان الإنسان، وأنّ الصدَّ عن الذكرِ من أعظمِ الجناية؛ فاحذر من يصدّك عن ذكرِ الله وكتابه، ولا تُطِع الشيطانَ فإنه خذولٌ لا يُغني عنك شيئًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":["وكان الشيطان للإنسان خذولا"],"heart_state":{"text":"الحذرُ ممّن يصدّ عن الذكر، ومن خذلانِ الشيطان."},"action":{"text":"احذر كلَّ خليلٍ أو داعٍ يصدّك عن ذكرِ الله وكتابه، ولا تُطِع الشيطانَ فإنه خذولٌ يزيّن لك المعصيةَ ثم يتركك عند الشدّة؛ فالزم القرآنَ والذكر، وصاحب من يعينك عليهما، فالصدُّ عن الذكرِ سببُ الحسرة."}}]},{"title":"هجرُ القرآن، وتثبيتُ الفؤادِ به","range":[30,34],"theme":"شكوى النبيِّ من هجرِ قومه للقرآن، وحكمةُ تنزيله مفرَّقًا","verses":[{"n":30,"reflection":{"text":"«وقال الرسول يا رب إن قومي اتخذوا هذا القرآن مهجورا» — وقال الرسولُ محمدٌ ﷺ شاكيًا: يا ربِّ إنّ قومي تركوا هذا القرآنَ وأعرضوا عنه فلم يؤمنوا به ولم يعملوا؛ ففي هذا التحذيرُ من هجرِ القرآن (بترْكِ تلاوته وتدبّرِه والعملِ به والتحاكمِ إليه)، وأنّ ذلك ممّا يشكوه النبيُّ ﷺ؛ فاحذر أن تهجر القرآنَ بأيِّ نوعٍ من الهجر، بل اتلُه وتدبّره واعمل به وتحاكم إليه، لئلا تكون ممّن يشكوهم النبيُّ ﷺ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["اتخذوا هذا القرآن مهجورا"],"heart_state":{"text":"الحذرُ من هجرِ القرآنِ بأنواعه."},"action":{"text":"احذر أن تهجر القرآنَ بترْكِ تلاوته أو تدبّرِه أو العملِ به أو التحاكمِ إليه أو التداوي به؛ فهجره ممّا يشكوه النبيُّ ﷺ إلى ربّه؛ فاجعل لك منه ورِدًا تتلوه وتتدبّره وتعمل به، لئلا تكون ممّن هجره."}},{"n":31,"reflection":{"text":"«وكذلك جعلنا لكل نبي عدوا من المجرمين وكفى بربك هاديا ونصيرا» — وكما جعلنا لك يا محمد أعداءً، جعلنا لكلِّ نبيٍّ عدوًّا من المجرمين يعاديه ويصدّ عن دعوته، وكفى بربّك هاديًا لك ونصيرًا؛ ففي هذا تسليةٌ للنبيِّ ﷺ بأنّ العداوةَ سنّةٌ، وأنّ الله كافٍ في الهدايةِ والنصر؛ فتسلَّ عند عداوةِ المبطلين لك بأنها سنّةٌ في الأنبياء، واكتفِ بالله هاديًا ونصيرًا، فمن كان الله معه فلا يضرّه عدوّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":["وكفى بربك هاديا ونصيرا"],"heart_state":{"text":"التسلّي بسنّةِ العداوة، والاكتفاءُ بالله هاديًا ونصيرًا."},"action":{"text":"تسلَّ عند عداوةِ المبطلين لك حين تدعو إلى الحقّ بأنها سنّةٌ لكلِّ نبيّ، واكتفِ بالله هاديًا لك ونصيرًا؛ فمن كان الله هاديه ونصيره فلا تضرّه عداوةُ المجرمين؛ فاعتمد عليه وحده، وامضِ في الحقِّ واثقًا بكفايته."}},{"n":32,"reflection":{"text":"«وقال الذين كفروا لولا نزل عليه القرآن جملة واحدة كذلك لنثبت به فؤادك ورتلناه ترتيلا» — وقال الكفار: هلّا نُزِّل القرآنُ عليه دفعةً واحدةً كالتوراة؟ نزّلناه مفرّقًا كذلك لنثبّت به فؤادك، وقرأناه عليك على مُكثٍ وترسّلٍ ليسهل حفظه وفهمه؛ ففي هذا حكمةُ تنزيلِ القرآنِ مفرّقًا: تثبيتُ القلبِ وتيسيرُ الحفظِ والعمل؛ فتلقَّ القرآنَ متمهّلًا مرتّلًا كما نزل، فبالترتيلِ والتمهّلِ يثبت في القلبِ ويُنتفَع به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["لنثبت به فؤادك","ورتلناه ترتيلا"],"heart_state":{"text":"تلقّي القرآنِ متمهّلًا مرتّلًا لتثبيتِ القلب."},"action":{"text":"اتلُ القرآنَ متمهّلًا مرتّلًا كما نزل مفرّقًا، فبالترتيلِ والتمهّلِ يثبت في القلبِ ويُتدبَّر ويُعمَل به؛ فلا تهذّه هذًّا، بل رتّله ترتيلًا وتوقّف عند معانيه؛ فحكمةُ تنزيله مفرّقًا تثبيتُ الفؤادِ وتيسيرُ الفهم."}},{"n":33,"reflection":{"text":"«ولا يأتونك بمثل إلا جئناك بالحق وأحسن تفسيرا» — ولا يأتيك المشركون بشبهةٍ أو مثلٍ يعارضون به الحقَّ إلا جئناك بالحقِّ الذي يدفعها وأحسنَ بيانًا وتفصيلًا؛ ففي هذا أنّ الله يكفي نبيَّه شبهاتِ المبطلين بالحقِّ الدامغ، وأنّ القرآنَ جوابٌ لكلِّ شبهة؛ فثق بأنّ الحقَّ يدفع كلَّ شبهة، والتمس في القرآنِ جوابَ ما يُلقى من الشبهات، فما من شبهةٍ إلا وفي الحقِّ ما يدحضها.","source":"تفسير السعدي","grade":"ma'thur"},"names":["إلا جئناك بالحق وأحسن تفسيرا"],"heart_state":{"text":"الثقةُ بأنّ الحقَّ يدفع كلَّ شبهة، والتماسُه في القرآن."},"action":{"text":"ثق بأنّ الله يكفيك شبهاتِ المبطلين بالحقِّ الدامغِ وأحسنِ البيان، فما من شبهةٍ إلا وفي الحقِّ ما يدحضها؛ فالتمس في القرآنِ والسنّةِ جوابَ ما يُلقى عليك من الشبهات، ولا تزعزعك، فالحقُّ أقوى من كلِّ باطل."}},{"n":34,"reflection":{"text":"«الذين يحشرون على وجوههم إلى جهنم أولئك شر مكانا وأضل سبيلا» — الذين يُساقون يوم القيامةِ يُسحَبون على وجوههم إلى جهنم، أولئك شرُّ الناسِ منزلًا وأضلُّهم طريقًا؛ ففي هذا إهانةُ المكذّبين بحشرهم على وجوههم، وأنهم شرُّ مكانًا وأضلُّ سبيلًا؛ فاحذر أن تكون من هؤلاء الذين ضلّ سبيلهم فحُشِروا على وجوههم، والزم الصراطَ المستقيمَ لتُحشَر مكرَّمًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من مصيرِ الضالّين والزومُ الصراطِ المستقيم."},"action":{"text":"احذر أن تكون من الضالّين الذين يُحشَرون على وجوههم إلى جهنمَ أذلّاء، والزم الصراطَ المستقيمَ الذي دعا إليه الرسول؛ فمن سلك سبيلَ الهدى حُشِر مكرَّمًا، ومن ضلّ سبيله حُشِر مهانًا؛ فاختر لنفسك خيرَ المكانِ والسبيل."}}]},{"title":"عبرةُ الأممِ المكذّبة","range":[35,40],"theme":"إهلاكُ قومِ موسى ونوحٍ وعادٍ وثمود، والاعتبارُ بآثارهم","verses":[{"n":35,"reflection":{"text":"«ولقد آتينا موسى الكتاب وجعلنا معه أخاه هارون وزيرا» — ولقد آتينا موسى التوراةَ، وجعلنا معه أخاه هارونَ معينًا ومؤازرًا في الرسالة؛ ففي هذا أنّ الله يؤيّد رسله بالكتابِ والعونِ الصالح، وأنّ التعاونَ على الحقِّ سنّة؛ فاطلب العونَ الصالحَ على الخير، واستعن بأهلِ الصلاحِ في أمورك، فالمؤمنُ للمؤمنِ كالبنيان.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ العونِ الصالحِ والتعاونُ على الحقّ."},"action":{"text":"اطلب من الله عونًا صالحًا يؤازرك على الحقِّ والدعوة، واستعن بأهلِ الصلاحِ في أمورك العظام، كما آزر الله موسى بأخيه هارون؛ فالتعاونُ على البرِّ سنّةُ الأنبياءِ وقوّةٌ في نصرِ الحقّ."}},{"n":36,"reflection":{"text":"«فقلنا اذهبا إلى القوم الذين كذبوا بآياتنا فدمرناهم تدميرا» — فقلنا لموسى وهارون: اذهبا إلى فرعونَ وقومه الذين كذّبوا بآياتنا فادعُواهم، فلمّا أصرّوا على التكذيبِ دمّرناهم تدميرًا؛ ففي هذا أنّ الدعوةَ تُقام على المكذّبين حجّةً، ثم يكون الهلاكُ بعد الإصرار؛ فبلّغ الحقَّ ولو للمعاندين، واعلم أنّ عاقبةَ المصرّين على التكذيبِ الدمار، فالزم أنت الحقَّ لتنجو.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إقامةُ الدعوةِ على المكذّبين، والعلمُ بعاقبةِ الإصرار."},"action":{"text":"بلّغ الحقَّ وادعُ إليه ولو المعاندين المكذّبين، فالحجّةُ تُقام عليهم أوّلًا؛ واعلم أنّ عاقبةَ المصرّين على التكذيبِ الدمارُ والهلاك؛ فالزم الحقَّ والتصديقَ لتنجو، ولا تكن من المكذّبين المصرّين."}},{"n":37,"reflection":{"text":"«وقوم نوح لما كذبوا الرسل أغرقناهم وجعلناهم للناس آية وأعتدنا للظالمين عذابا أليما» — وقومَ نوحٍ لمّا كذّبوا الرسلَ أغرقناهم بالطوفان، وجعلناهم للناسِ عبرةً وعظة، وأعتدنا للظالمين عذابًا أليمًا؛ ففي هذا أنّ تكذيبَ الرسلِ سببُ الهلاك، وأنّ في مصارعِ الأممِ عبرةً؛ فاعتبر بهلاكِ قومِ نوحٍ وغيرهم، واحذر التكذيبَ والظلم، فعاقبتهما العذابُ الأليم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بهلاكِ المكذّبين والحذرُ من الظلم."},"action":{"text":"اعتبر بهلاكِ قومِ نوحٍ وسائرِ الأممِ التي كذّبت رسلها فأهلكها الله وجعلها آيةً وعبرة، واحذر التكذيبَ بالحقِّ والظلمَ فعاقبتهما العذابُ الأليم؛ فالزم التصديقَ والعدلَ لتنجو، فالعاقبةُ للمؤمنين المتّقين."}},{"n":38,"reflection":{"text":"«وعادا وثمود وأصحاب الرس وقرونا بين ذلك كثيرا» — وأهلكنا عادًا (قومَ هود) وثمودَ (قومَ صالح) وأصحابَ الرسِّ (أصحابَ البئرِ) وأممًا كثيرةً بين ذلك؛ ففي هذا كثرةُ من أهلكهم الله من المكذّبين، وأنّ سنّتَه في إهلاكِ الظالمين ماضية؛ فاعتبر بكثرةِ من أهلكهم الله، واحذر أن تسلك سبيلهم، فسنّةُ الله في المكذّبين واحدة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بكثرةِ المُهلَكين وعدمُ سلوكِ سبيلهم."},"action":{"text":"اعتبر بكثرةِ الأممِ التي أهلكها الله بتكذيبها ــ عادٍ وثمودَ وأصحابِ الرسِّ وغيرهم ــ واحذر أن تسلك سبيلهم في التكذيبِ والمعصية؛ فسنّةُ الله في المكذّبين ماضيةٌ لا تتخلّف، فالزم الحقَّ لتنجو من مصيرهم."}},{"n":39,"reflection":{"text":"«وكلا ضربنا له الأمثال وكلا تبرنا تتبيرا» — وكلُّ أمّةٍ من هؤلاء بيّنّا لها الحججَ وضربنا لها الأمثالَ لتتّعظ، فلمّا كذّبوا أهلكناهم إهلاكًا تامًّا؛ ففي هذا أنّ الله أقام الحجّةَ على الأممِ قبل إهلاكهم، وأنّ الإهلاكَ بعد البيان؛ فاتّعظ بالأمثالِ والحججِ التي بيّنها الله لك قبل أن تنالك عقوبةُ المكذّبين، فالحجّةُ قامت عليك بالقرآن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ بالحججِ والأمثالِ قبل نزولِ العقوبة."},"action":{"text":"اتّعظ بما ضرب الله لك من الأمثالِ وأقام من الحججِ في القرآن، قبل أن تنالك عقوبةُ المكذّبين؛ فالله لا يهلك أمّةً إلا بعد إقامةِ الحجّة، وقد قامت عليك بالقرآن؛ فبادر بالاتّعاظِ والعمل، ولا تكذّب فتهلك."}},{"n":40,"reflection":{"text":"«ولقد أتوا على القرية التي أمطرت مطر السوء أفلم يكونوا يرونها بل كانوا لا يرجون نشورا» — ولقد مرّ كفارُ قريشٍ في أسفارهم على قريةِ قومِ لوطٍ التي أُمطِرت بالحجارة، أفلم يكونوا يرونها فيعتبروا؟ بل كانوا لا يرجون بعثًا ولا يخافونه فلم يتّعظوا؛ ففي هذا أنّ إنكارَ البعثِ يمنع الاتّعاظَ بالآيات، وأنّ رجاءَ البعثِ يبعث على العبرة؛ فاعتبر بآثارِ المهلَكين، وأيقن بالبعثِ فإنه يحملك على الاتّعاظِ والعمل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بآثارِ المهلَكين، واليقينُ بالبعثِ الباعثِ على العبرة."},"action":{"text":"اعتبر بآثارِ الأممِ المهلَكةِ التي ترى ديارها وتسمع أخبارها، وأيقن بالبعثِ والجزاء؛ فإنكارُ البعثِ يمنع الاتّعاظ، ورجاؤه يحمل على العبرةِ والعمل؛ فلا تمرّ على آياتِ الله وعبرِه غافلًا كالمكذّبين."}}]},{"title":"استهزاؤهم بالرسول، وعبادةُ الهوى","range":[41,44],"theme":"سخريةُ الكفارِ من النبيّ، ومن اتّخذ إلهه هواه، وأنهم كالأنعام","verses":[{"n":41,"reflection":{"text":"«وإذا رأوك إن يتخذونك إلا هزوا أهذا الذي بعث الله رسولا» — وإذا رآك المشركون ما يتّخذونك إلا موضعَ سخرية، يقولون استهزاءً: أهذا الذي بعثه الله رسولًا إلينا؟ ففي هذا صبرُ النبيِّ ﷺ على استهزائهم، وأنّ المستهزئَ يحتقر الحقَّ وأهله؛ فاصبر على استهزاءِ السفهاءِ بك لأجلِ الحقّ، ولا يصدّنك ذلك عن دينك، فاستهزاؤهم علامةُ سفههم لا نقصٍ فيك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على الاستهزاءِ لأجلِ الحقّ."},"action":{"text":"اصبر على استهزاءِ الجاهلين بك حين تلزم الحقَّ وتدعو إليه، ولا يصدّنك سخرهم عن دينك؛ فاستهزاؤهم دليلُ سفههم واحتقارهم للحقّ، لا نقصٍ فيك؛ فامضِ في الحقِّ واثقًا، فالعاقبةُ لأهله لا للمستهزئين."}},{"n":42,"reflection":{"text":"«إن كاد ليضلنا عن آلهتنا لولا أن صبرنا عليها وسوف يعلمون حين يرون العذاب من أضل سبيلا» — يقولون: قارب هذا الرسولُ أن يصرفنا عن عبادةِ آلهتنا لولا أن ثبتنا عليها، وسوف يعلمون حين يرون العذابَ من هو أضلُّ سبيلًا؛ ففي هذا اعترافهم بقوّةِ حجّةِ الحقِّ وأنها كادت تزحزحهم، وتهديدُهم بأنّ الحقيقةَ تنكشف عند العذاب؛ فاعلم أنّ الحقَّ قويٌّ يزلزل الباطل، وأنّ الضلالَ يتبيّن عند العذاب، فالزم الحقَّ ولا تكابر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العلمُ بقوّةِ الحقِّ وأنّ الضلالَ يتبيّن عند العذاب."},"action":{"text":"اعلم أنّ الحقَّ قويٌّ يكاد يزلزل أهلَ الباطلِ لولا مكابرتهم، وأنّ الحقيقةَ تنكشف عند رؤيةِ العذابِ فيتبيّن من أضلُّ سبيلًا؛ فالزم الحقَّ ولا تكابر عليه بعد وضوحه، فمكابرةُ الحقِّ خسرانٌ يظهر يوم القيامة."}},{"n":43,"reflection":{"text":"«أرأيت من اتخذ إلهه هواه أفأنت تكون عليه وكيلا» — أرأيت يا محمد من جعل هواه إلهًا يطيعه ويقدّمه على أمرِ الله، أفأنت تكون عليه حفيظًا تلزمه الهدى؟ ليس ذلك إليك؛ ففي هذا ذمُّ اتّباعِ الهوى حتى يصير كالمعبود، وأنّ من هذا حاله لا يُرجى هداه؛ فاحذر أن تجعل هواك إلهًا تطيعه، بل أخضع هواك لأمرِ الله، فمن اتّبع هواه ضلَّ وإن سمع الحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["من اتخذ إلهه هواه"],"heart_state":{"text":"الحذرُ من اتّخاذِ الهوى إلهًا وإخضاعُه لأمرِ الله."},"action":{"text":"احذر أن تجعل هواك إلهًا تطيعه وتقدّمه على أمرِ الله ورسوله، فمن عبد هواه ضلَّ ولو سمع الحقّ؛ بل أخضع هواك ورغبتك لشرعِ الله، وزِن ميولك بميزانِ الوحي؛ فمخالفةُ الهوى في مرضاةِ الله رأسُ الحكمة."}},{"n":44,"reflection":{"text":"«أم تحسب أن أكثرهم يسمعون أو يعقلون إن هم إلا كالأنعام بل هم أضل سبيلا» — أم تظنّ أنّ أكثرهم يسمعون الحقَّ سماعَ انتفاعٍ أو يعقلونه؟ ما هم في إعراضهم إلا كالأنعامِ التي لا تعقل، بل هم أضلُّ سبيلًا منها؛ ففي هذا أنّ من لم ينتفع بسمعه وعقله في معرفةِ الحقِّ فهو كالأنعامِ بل أضلّ، وأنّ العقلَ نعمةٌ تُستعمَل في الهدى؛ فاستعمل سمعك وعقلك في فهمِ الحقِّ والعملِ به، ولا تكن كالأنعامِ الغافلة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["إن هم إلا كالأنعام بل هم أضل سبيلا"],"heart_state":{"text":"استعمالُ السمعِ والعقلِ في فهمِ الحقِّ والعملِ به."},"action":{"text":"استعمل سمعك وعقلك في فهمِ الحقِّ والاهتداءِ به والعملِ به، فمن عطّلهما عن ذلك فهو كالأنعامِ بل أضلُّ سبيلًا؛ فالعقلُ والسمعُ نعمتان خُلِقتا لتوصلاك إلى ربّك؛ فلا تكن من الغافلين الذين لا يسمعون ولا يعقلون."}}]},{"title":"آياتُ الله في الظلِّ والليلِ والماء","range":[45,50],"theme":"مدُّ الظلّ، والليلُ لباسًا والنومُ سباتًا، والرياحُ والماءُ الطهور","verses":[{"n":45,"reflection":{"text":"«ألم تر إلى ربك كيف مد الظل ولو شاء لجعله ساكنا ثم جعلنا الشمس عليه دليلا» — ألم تنظر إلى صنعِ ربّك كيف بسط الظلَّ (من الفجرِ إلى طلوعِ الشمس)، ولو شاء لجعله ثابتًا لا يزول، ثم جعلنا الشمسَ دليلًا عليه تتبعه فيتقلّص؛ ففي هذا آيةٌ من آياتِ لطفِ الله وتدبيرِه في الظلِّ والشمس، وأنّ في ذلك نعمةً ورحمة؛ فتأمّل نعمةَ الظلِّ والشمسِ وتدبيرَ الله فيهما، فكلُّها آياتٌ تدلّ على لطفه وحكمته، تدعوك لشكره وعبادته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في آياتِ الله في الظلِّ والشمس، وشكرُها."},"action":{"text":"تأمّل في صنعِ الله وتدبيرِه في مدِّ الظلِّ وجعلِ الشمسِ دليلًا عليه، فذلك آيةٌ على لطفه وحكمته ورحمته؛ فاشكر نعمةَ الظلِّ والضياءِ التي تعيش بها، ولا تمرّ على آياتِ الله في الكونِ غافلًا، بل اعتبر واشكر."}},{"n":46,"reflection":{"text":"«ثم قبضناه إلينا قبضا يسيرا» — ثم قبضنا الظلَّ إلينا قبضًا سهلًا يسيرًا بطلوعِ الشمسِ شيئًا فشيئًا؛ ففي هذا تمامُ آيةِ الظلِّ وتدبيرِ الله فيه بلطفٍ وتدرّج، وأنّ ذلك يسيرٌ على الله؛ فتأمّل لطفَ الله في تدبيرِ الظلِّ والنور بالتدرّجِ لا فجأة، فرحمتُه في تدرّجِ تدبيره، فاشكره على لطفه وحكمته في كلِّ شيء.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تأمّلُ لطفِ الله في تدرّجِ تدبيره."},"action":{"text":"تأمّل لطفَ الله في قبضِ الظلِّ بالتدرّجِ اليسيرِ لا فجأة، ففي تدرّجِ تدبيره رحمةٌ بك؛ فاشكره على لطفه وحكمته في تدبيرِ الكونِ والنعم، واعلم أنّ ما يجري بلطفٍ وتدرّجٍ خيرٌ لك من المفاجأة، فارضَ بتدبيره."}},{"n":47,"reflection":{"text":"«وهو الذي جعل لكم الليل لباسا والنوم سباتا وجعل النهار نشورا» — وهو الذي جعل لكم الليلَ ساترًا كاللباسِ تسكنون فيه، والنومَ راحةً لأبدانكم، وجعل النهارَ وقتَ انتشارٍ للمعاشِ والسعي؛ ففي هذا تعدادُ نعمِ الله في الليلِ والنومِ والنهار، وأنها آياتٌ ونعمٌ تستوجب الشكر؛ فاشكر الله على نعمةِ الليلِ والراحةِ والنهارِ للسعي، فكلُّها من تدبيرِه ورحمته، ولا تنسَ المُنعِمَ في سكونك وحركتك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["جعل لكم الليل لباسا والنوم سباتا"],"heart_state":{"text":"شكرُ نعمِ الليلِ والنومِ والنهار."},"action":{"text":"اشكر الله على نعمةِ الليلِ الذي يسترك ويسكّنك، والنومِ الذي يريح بدنك، والنهارِ الذي تنتشر فيه لمعاشك؛ فكلُّها نعمٌ من تدبيرِه ورحمته؛ فاذكره عند نومك ويقظتك، واستعمل نهارك في طاعته وسعيك المباح."}},{"n":48,"reflection":{"text":"«وهو الذي أرسل الرياح بشرا بين يدي رحمته وأنزلنا من السماء ماء طهورا» — وهو الذي أرسل الرياحَ مبشّراتٍ بين يدي المطرِ (رحمته)، وأنزلنا من السماءِ ماءً طهورًا في نفسه مطهّرًا لغيره؛ ففي هذا نعمةُ الرياحِ المبشّرةِ والماءِ الطهور، وأنّ الماءَ يطهّر الحدثَ والخبث؛ فاشكر نعمةَ الماءِ الطهور الذي به طهارتك وحياتك، واستعمله في طهارتك لعبادةِ الله، فهو من أعظمِ نعمِه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["أنزلنا من السماء ماء طهورا"],"heart_state":{"text":"شكرُ نعمةِ الماءِ الطهورِ واستعمالُه في الطهارة."},"action":{"text":"اشكر الله على نعمةِ الرياحِ المبشّرةِ بالمطر، والماءِ الطهورِ الذي به طهارتك وحياتك؛ واستعمله في الوضوءِ والغسلِ لعبادةِ الله؛ فالماءُ من أعظمِ نعمِ الله، طهورٌ في نفسه مطهّرٌ لغيره، فلا تسرف فيه واشكر مُنعِمه."}},{"n":49,"reflection":{"text":"«لنحيي به بلدة ميتا ونسقيه مما خلقنا أنعاما وأناسي كثيرا» — لنحييَ بذلك الماءِ أرضًا ميتةً بالنبات، ونسقيَه لما خلقنا من الأنعامِ والناسِ الكثيرين؛ ففي هذا بيانُ منافعِ الماءِ في إحياءِ الأرضِ وسقيِ الخلق، وأنّ في إحياءِ الأرضِ دليلًا على البعث؛ فتأمّل كيف يحيي الله الأرضَ الميتةَ بالماء، واعلم أنّ من أحياها يحيي الموتى، فاشكر نعمةَ الماءِ وأيقن بالبعث.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["لنحيي به بلدة ميتا"],"heart_state":{"text":"تأمّلُ إحياءِ الأرضِ دليلًا على البعثِ وشكرُ الماء."},"action":{"text":"تأمّل كيف يحيي الله الأرضَ الميتةَ بالماءِ ويسقي به الأنعامَ والناس، فذلك نعمةٌ ودليلٌ على البعث؛ فاشكر نعمةَ الماءِ التي بها حياةُ كلِّ شيء، وأيقن بأنّ من أحيا الأرضَ الميتةَ قادرٌ على إحيائك بعد موتك."}},{"n":50,"reflection":{"text":"«ولقد صرفناه بينهم ليذكروا فأبى أكثر الناس إلا كفورا» — ولقد نوّعنا المطرَ (أو القرآنَ والحججَ) بينهم ليتذكّروا نعمةَ الله فيشكروه، فأبى أكثرُ الناسِ إلا جحودًا للنعمةِ وكفرًا؛ ففي هذا أنّ نعمَ الله تُصرَّف بين الناسِ ليشكروا، وأنّ أكثرهم يقابلونها بالكفر؛ فقابل نعمَ الله بالشكرِ لا بالكفر، ولا تكن من الأكثرِ الجاحدِ للنعم، بل اذكرها واحمد الله عليها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"مقابلةُ نعمِ الله بالشكرِ لا بالكفران."},"action":{"text":"قابل نعمَ الله المتنوّعةَ عليك بالشكرِ والذكرِ والطاعة، ولا تكن من أكثرِ الناسِ الذين يقابلونها بالجحودِ والكفران؛ فالنعمُ تُصرَّف بينكم ليتذكّر الناسُ المُنعِمَ فيشكروه؛ فاجعل كلَّ نعمةٍ سببًا لحمدِ الله وطاعته."}}]},{"title":"الأمرُ بجهادِ الكفارِ بالقرآن","range":[51,54],"theme":"عدمُ طاعةِ الكفار، وجهادُهم بالقرآن، وآياتُ البحرين والنسب","verses":[{"n":51,"reflection":{"text":"«ولو شئنا لبعثنا في كل قرية نذيرا» — ولو شئنا لبعثنا في كلِّ قريةٍ رسولًا ينذرها، لكنا خصصناك يا محمد بالرسالةِ العامّةِ للناسِ كافّة؛ ففي هذا بيانُ عمومِ رسالةِ النبيِّ ﷺ وشرفِها، وأنّ ذلك من فضلِ الله ومشيئته؛ فاشكر الله على نعمةِ هذا الرسولِ الخاتمِ الذي عمّت رسالته، واحمل أمانةَ تبليغِ ما بلغك من دعوته، فأنت من أمّةِ البلاغ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ عمومِ الرسالةِ الخاتمة، وحملُ أمانةِ البلاغ."},"action":{"text":"اشكر الله على نعمةِ الرسولِ الخاتمِ الذي عمّت رسالته الناسَ كافّةً بفضلِ الله؛ واحمل أمانةَ تبليغِ ما بلغك من دينه ودعوته لغيرك؛ فأنت من أمّةِ البلاغ، فكن نذيرًا في موضعك بما تستطيع من دعوةٍ وقدوة."}},{"n":52,"reflection":{"text":"«فلا تطع الكافرين وجاهدهم به جهادا كبيرا» — فلا تطع الكافرين فيما يدعونك إليه من ترْكِ الحقّ، وجاهدهم بالقرآنِ (بالحجّةِ والبيان) جهادًا كبيرًا؛ ففي هذا الأمرُ بالثباتِ وعدمِ مداهنةِ الكفار، وأنّ القرآنَ سلاحُ الجهادِ بالحجّة؛ فلا تطع من يدعوك لترْكِ الحقّ، وجاهد بالقرآنِ حجّةً وبيانًا ودعوة، فهو أعظمُ سلاحٍ في نصرةِ الحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["وجاهدهم به جهادا كبيرا"],"heart_state":{"text":"عدمُ طاعةِ الكفار، والجهادُ بالقرآنِ حجّةً ودعوة."},"action":{"text":"لا تطع من يدعوك إلى ترْكِ الحقِّ أو مداهنةِ الباطل، وجاهد بالقرآنِ جهادًا كبيرًا: احتجاجًا به وبيانًا لحقائقه ودعوةً إليه؛ فالقرآنُ أعظمُ سلاحٍ في نصرةِ الحقّ، فاستعمله في دعوتك وثباتك، ولا تلن لأهلِ الباطل."}},{"n":53,"reflection":{"text":"«وهو الذي مرج البحرين هذا عذب فرات وهذا ملح أجاج وجعل بينهما برزخا وحجرا محجورا» — وهو الذي أرسل البحرين متجاورين: هذا عذبٌ شديدُ العذوبة، وهذا ملحٌ شديدُ الملوحة، وجعل بينهما حاجزًا يمنع اختلاطَهما وفسادَ أحدهما بالآخر؛ ففي هذا آيةٌ من آياتِ قدرةِ الله ولطفه في الفصلِ بين الماءين المتجاورين؛ فتأمّل قدرةَ الله في هذه الآيةِ العجيبة، فمن فصل بين العذبِ والملحِ مع تجاورهما قادرٌ على كلِّ شيء، فاعبده وحده وعظّم قدرته.","source":"تفسير السعدي","grade":"ma'thur"},"names":["مرج البحرين","وجعل بينهما برزخا وحجرا محجورا"],"heart_state":{"text":"التأمّلُ في آيةِ البحرين دليلًا على قدرةِ الله."},"action":{"text":"تأمّل قدرةَ الله ولطفه في الفصلِ بين الماءِ العذبِ والملحِ مع تجاورهما، فذلك آيةٌ عجيبةٌ على قدرته وحكمته؛ فمن قدر على ذلك قادرٌ على كلِّ شيء؛ فاعبده وحده وعظّم قدرته، ولا تمرّ على آياته في الكونِ غافلًا."}},{"n":54,"reflection":{"text":"«وهو الذي خلق من الماء بشرا فجعله نسبا وصهرا وكان ربك قديرا» — وهو الذي خلق من الماءِ (النطفةِ) بشرًا، فجعل منه ذوي نسبٍ (قرابةِ الدم) وصهرٍ (قرابةِ الزواج)، وكان ربّك قديرًا؛ ففي هذا آيةُ خلقِ الإنسانِ من ماءٍ مهينٍ وجعلِ منه أنواعَ القراباتِ، وأنّ ذلك دليلُ قدرةِ الله؛ فتأمّل نعمةَ النسبِ والصهرِ التي بها تُبنى المجتمعات، واشكر الله على قدرته التي خلقت منك أنواعَ القرابات، وصِل رحمك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["فجعله نسبا وصهرا","وكان ربك قديرا"],"heart_state":{"text":"تأمّلُ نعمةِ النسبِ والصهر، وصلةُ الرحم."},"action":{"text":"تأمّل قدرةَ الله التي خلقت من الماءِ بشرًا وجعلت منه قراباتِ النسبِ والصهرِ التي بها تُبنى الأسرُ والمجتمعات؛ واشكر هذه النعمة، وصِل رحمك وأحسن إلى أقاربك وأصهارك؛ فمن عرف نعمةَ القرابةِ رعى حقوقها ووصلها."}}]},{"title":"وظيفةُ الرسول، والأمرُ بالتوكّلِ والتسبيح","range":[55,60],"theme":"عبادةُ الكفارِ ما لا ينفع، والتوكّلُ على الحيِّ الذي لا يموت، وتعظيمُ الرحمن","verses":[{"n":55,"reflection":{"text":"«ويعبدون من دون الله ما لا ينفعهم ولا يضرهم وكان الكافر على ربه ظهيرا» — ويعبد المشركون من دون الله ما لا ينفعهم إن عبدوه ولا يضرّهم إن تركوه، وكان الكافرُ معينًا للشيطانِ على معصيةِ ربّه؛ ففي هذا إبطالُ عبادةِ ما لا ينفع ولا يضرّ، وأنّ الكافرَ يعين على الباطل؛ فلا تعبد إلا من ينفعك ويضرّك وهو الله، ولا تكن معينًا على معصيةِ الله، بل كن عونًا على طاعته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إفرادُ الله بالعبادة، وعدمُ الإعانةِ على معصيته."},"action":{"text":"لا تعبد ولا ترجُ إلا الله الذي يملك نفعك وضرّك، فما سواه لا ينفع ولا يضرّ؛ ولا تكن معينًا على معصيةِ الله كالكافر، بل كن عونًا على طاعته ونصرةِ دينه؛ فأخلص العبادةَ للنافعِ الضارِّ وحده، وأعِن على البرِّ لا على الإثم."}},{"n":56,"reflection":{"text":"«وما أرسلناك إلا مبشرا ونذيرا» — وما أرسلناك يا محمد إلا مبشّرًا للمؤمنين بالثواب، ونذيرًا للكافرين من العقاب؛ ففي هذا بيانُ وظيفةِ الرسولِ بالتبشيرِ والإنذار، وأنّ الهدايةَ بيدِ الله؛ فتلقَّ بشارةَ الرسولِ ونذارته بالعمل، وكن من أهلِ البشرى بالإيمانِ والطاعة، لا من أهلِ النذارةِ بالكفرِ والعصيان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تلقّي بشارةِ الرسولِ ونذارته بالعمل."},"action":{"text":"تلقَّ بشارةَ الرسولِ ﷺ للمؤمنين ونذارته للعاصين بالعمل، واجعل نفسك من أهلِ البشرى بالإيمانِ والطاعةِ والإحسان، لا من أهلِ النذارةِ بالكفرِ والمعصية؛ فوظيفةُ الرسولِ البلاغ، والانتفاعُ بسعيك واختيارك."}},{"n":57,"reflection":{"text":"«قل ما أسألكم عليه من أجر إلا من شاء أن يتخذ إلى ربه سبيلا» — قل: ما أطلب منكم على تبليغِ الرسالةِ أجرًا من مالٍ، لكن من شاء أن يتّخذ إلى ربّه سبيلًا بالإيمانِ والطاعةِ فليفعل، فذلك نفعه لنفسه؛ ففي هذا أنّ الداعيَ لا يطلب أجرًا من الناس، وأنّ نفعَ الاستجابةِ يعود على المستجيب؛ فادعُ إلى الله محتسبًا لا طالبًا أجرًا، واتّخذ إلى ربّك سبيلًا بالطاعة، فنفعُ ذلك لك.","source":"تفسير السعدي","grade":"ma'thur"},"names":["من شاء أن يتخذ إلى ربه سبيلا"],"heart_state":{"text":"الدعوةُ بلا أجرٍ من الناس، واتّخاذُ السبيلِ إلى الله."},"action":{"text":"ادعُ إلى الله وأحسِن محتسبًا أجرك عليه لا على الناس؛ واتّخذ إلى ربّك سبيلًا بالإيمانِ والطاعةِ والإنفاق، فنفعُ ذلك يعود عليك؛ فلا تطلب على الخيرِ عوضًا من الخلق، واجعل كلَّ عملٍ قربةً تتّخذ بها إلى الله سبيلًا."}},{"n":58,"reflection":{"text":"«وتوكل على الحي الذي لا يموت وسبح بحمده وكفى به بذنوب عباده خبيرا» — وتوكّل على الله الحيِّ الذي لا يموت في جميعِ أمورك، وسبّح بحمده منزّهًا له، وكفى به عليمًا خبيرًا بذنوبِ عباده يجازيهم عليها؛ ففي هذا الأمرُ بالتوكّلِ على الحيِّ الباقي، والتسبيحِ بحمده، وأنّ الله خبيرٌ بالذنوب؛ فتوكّل على الله وحده الذي لا يموت، وسبّح بحمده، واعلم أنه خبيرٌ بعملك، فأخلص له واعتمد عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["وتوكل على الحي الذي لا يموت","وسبح بحمده"],"heart_state":{"text":"التوكّلُ على الحيِّ الذي لا يموت، وتسبيحُه بحمده."},"action":{"text":"توكّل على الله الحيِّ الذي لا يموت في كلِّ أمورك، ولا تعتمد على مخلوقٍ يموت ويزول؛ وسبّح بحمده منزّهًا له في كلِّ حين؛ واعلم أنه خبيرٌ بذنوبك وأعمالك؛ فأخلص له عملك، واعتمد عليه وحده، فمن توكّل على الحيِّ الباقي كُفِي."}},{"n":59,"reflection":{"text":"«الذي خلق السماوات والأرض وما بينهما في ستة أيام ثم استوى على العرش الرحمن فاسأل به خبيرا» — هو الذي خلق السماواتِ والأرضَ وما بينهما في ستةِ أيامٍ (مع قدرته على خلقها في لحظة، لحكمةِ التأنّي)، ثم استوى على العرشِ استواءً يليق بجلاله، الرحمنُ، فاسأل عنه عليمًا خبيرًا (هو الله أو أهلُ العلمِ به)؛ ففي هذا إثباتُ الخلقِ والاستواءِ على ما يليق بالله، واسمِه الرحمن؛ فعظّم الله الخالقَ المستويَ على عرشه، الرحمنَ، وأثبت له ما أثبته لنفسه بلا تكييف، واعبده وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":["ثم استوى على العرش","الرحمن"],"heart_state":{"text":"تعظيمُ الله الخالقِ الرحمنِ وإثباتُ صفاته."},"action":{"text":"عظّم الله الذي خلق السماواتِ والأرضَ واستوى على عرشه استواءً يليق بجلاله، الرحمنَ الواسعَ الرحمة؛ وأثبت له من الصفاتِ ما أثبته لنفسه بلا تكييفٍ ولا تشبيه؛ فاعبده وحده، واسأله من رحمته، فمن عرف عظمته وسعةَ رحمته أخلص له العبادة."}},{"n":60,"reflection":{"text":"«وإذا قيل لهم اسجدوا للرحمن قالوا وما الرحمن أنسجد لما تأمرنا وزادهم نفورا» — وإذا قيل للمشركين: اسجدوا للرحمنِ، قالوا استكبارًا وجهلًا: وما الرحمنُ؟ أنسجد لما تأمرنا به؟ وزادهم الأمرُ بالسجودِ نفورًا عن الحقّ؛ ففي هذا أنّ الكِبرَ والجهلَ يحملان على النفورِ من عبادةِ الله، وأنّ القلبَ القاسيَ يزداد بالتذكيرِ نفورًا؛ فاحذر أن يزيدك التذكيرُ نفورًا، بل اسجد للرحمنِ خاضعًا، فالسجودُ له عزٌّ وكرامة، والنفورُ منه شقاء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الخضوعُ بالسجودِ للرحمن، والحذرُ من النفورِ عن الحقّ."},"action":{"text":"اسجد للرحمنِ خاضعًا محبًّا معظّمًا، ولا تكن كالمستكبرين الذين يزيدهم التذكيرُ نفورًا؛ فالسجودُ لله عزٌّ وكرامةٌ وقربى، والنفورُ عنه كِبرٌ وشقاء؛ فلِن قلبك للحقِّ عند سماعه، ولا تدع الكِبرَ يحجبك عن الخضوعِ لربّك."}}]},{"title":"البروجُ والليلُ والنهار، وأوّلُ صفاتِ عبادِ الرحمن","range":[61,64],"theme":"آياتُ السماء، والتذكّرُ والشكر، وتواضعُ عبادِ الرحمنِ وقيامُهم","verses":[{"n":61,"reflection":{"text":"«تبارك الذي جعل في السماء بروجا وجعل فيها سراجا وقمرا منيرا» — تعاظم الله الذي جعل في السماءِ منازلَ للكواكبِ (بروجًا)، وجعل فيها الشمسَ سراجًا وهّاجًا والقمرَ منيرًا؛ ففي هذا آياتُ عظمةِ الله في السماءِ وزينتِها ومنافعِها، وأنها تدلّ على بركتِه؛ فتأمّل آياتِ السماءِ من بروجٍ وشمسٍ وقمر، فذلك يدلّ على عظمةِ خالقها وبركتِه، فعظّمه واعبده وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":["تبارك الذي جعل في السماء بروجا"],"heart_state":{"text":"التأمّلُ في آياتِ السماء، وتعظيمُ خالقها."},"action":{"text":"تأمّل في آياتِ السماءِ من البروجِ والشمسِ والقمر، فذلك يدلّ على عظمةِ الله وبركتِه وحكمتِه؛ فعظّم خالقها الذي تبارك، واعبده وحده، ولا ترفع بصرك إلى السماءِ غافلًا، بل معتبرًا بآيات ربّك."}},{"n":62,"reflection":{"text":"«وهو الذي جعل الليل والنهار خلفة لمن أراد أن يذكر أو أراد شكورا» — وهو الذي جعل الليلَ والنهارَ يخلف كلٌّ منهما الآخر، لمن أراد أن يتذكّر بهما فيعتبر، أو أراد أن يشكر الله على نعمهما، أو يتدارك ما فاته في أحدهما بالآخر؛ ففي هذا أنّ تعاقبَ الليلِ والنهارِ فرصةٌ للذكرِ والشكرِ والتدارك؛ فاغتنم الليلَ والنهارَ في ذكرِ الله وشكره، وتدارك ما فاتك من طاعةٍ في أحدهما بالآخر، فهما ميدانُ العمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["جعل الليل والنهار خلفة لمن أراد أن يذكر أو أراد شكورا"],"heart_state":{"text":"اغتنامُ الليلِ والنهارِ في الذكرِ والشكرِ والتدارك."},"action":{"text":"اغتنم الليلَ والنهارَ في ذكرِ الله وشكره وطاعته، وتدارك ما فاتك من وردٍ أو طاعةٍ في أحدهما بالآخر؛ فقد جعلهما الله يخلف أحدهما الآخر فرصةً للعملِ والتذكّر؛ فلا تدع وقتًا يمرّ بلا ذكرٍ أو شكرٍ أو عمل."}},{"n":63,"reflection":{"text":"«وعباد الرحمن الذين يمشون على الأرض هونا وإذا خاطبهم الجاهلون قالوا سلاما» — وعبادُ الرحمنِ (المكرَمون بإضافتهم إليه) الذين يمشون على الأرضِ بسكينةٍ وتواضعٍ لا كِبرَ فيه، وإذا خاطبهم الجاهلون بالسفهِ والأذى ردّوا بالسلامةِ والقولِ الحسنِ ولم يجاهلوهم؛ ففي هذا أوّلُ صفاتِ عبادِ الرحمن: التواضعُ في المشي، والحلمُ عن الجاهلين؛ فتخلّق بالتواضعِ والحلم، وامشِ بسكينة، وقابل سفهَ الجاهلين بالحلمِ والسلام، فتلك صفةُ عبادِ الرحمن.","source":"تفسير السعدي","grade":"ma'thur"},"names":["يمشون على الأرض هونا","وإذا خاطبهم الجاهلون قالوا سلاما"],"heart_state":{"text":"التواضعُ في المشي، والحلمُ عن الجاهلين."},"action":{"text":"تخلّق بصفاتِ عبادِ الرحمن: امشِ على الأرضِ بتواضعٍ وسكينةٍ لا كِبرَ فيه ولا خيلاء، وإذا خاطبك الجاهلون بالسفهِ فقابلهم بالحلمِ والسلامِ والقولِ الحسن، ولا تجاهلهم؛ فالحلمُ عن الجاهلِ من أخلاقِ عبادِ الرحمن."}},{"n":64,"reflection":{"text":"«والذين يبيتون لربهم سجدا وقياما» — والذين يقضون الليلَ أو بعضه لربّهم ساجدين قائمين في الصلاة (قيامُ الليل)؛ ففي هذا أنّ من صفاتِ عبادِ الرحمنِ قيامَ الليلِ والتهجّد، وأنّ الخلوةَ بالله بالليلِ شرفٌ لهم؛ فاجعل لك من الليلِ نصيبًا من سجودٍ وقيامٍ لله، فقيامُ الليلِ دأبُ الصالحين وشرفُ المؤمن، به تُنال المنازلُ العالية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["يبيتون لربهم سجدا وقياما"],"heart_state":{"text":"اتّخاذُ نصيبٍ من الليلِ للسجودِ والقيامِ لله."},"action":{"text":"اجعل لك من الليلِ نصيبًا تقوم فيه لله ساجدًا قائمًا متهجّدًا، فقيامُ الليلِ من صفاتِ عبادِ الرحمنِ ودأبِ الصالحين وشرفِ المؤمن؛ فاغتنم جوفَ الليلِ في مناجاةِ ربّك، فهو أزكى للعملِ وأرجى للقبول."}}]},{"title":"صفاتُ عبادِ الرحمن: الخوفُ والاعتدالُ والتوحيد","range":[65,71],"theme":"دعاؤهم بصرفِ العذاب، واعتدالُهم في الإنفاق، واجتنابُهم الكبائرَ والتوبة","verses":[{"n":65,"reflection":{"text":"«والذين يقولون ربنا اصرف عنا عذاب جهنم إن عذابها كان غراما» — والذين يدعون: ربّنا اصرف عنا عذابَ جهنم، إنّ عذابها كان ملازمًا دائمًا لا يفارق أهله؛ ففي هذا أنّ من صفاتِ عبادِ الرحمنِ الخوفَ من النارِ والدعاءَ بصرفها، وأنّ عذابها ملازم؛ فاخف النارَ وادعُ الله أن يصرفها عنك، فالخوفُ منها يحمل على العمل، ودعاءُ صرفها من دأبِ الصالحين.","source":"تفسير السعدي","grade":"ma'thur"},"names":["ربنا اصرف عنا عذاب جهنم"],"heart_state":{"text":"الخوفُ من النارِ والدعاءُ بصرفِ عذابها."},"action":{"text":"اخف النارَ واستحضر دوامَ عذابها، وادعُ الله أن يصرفه عنك؛ فالخوفُ منها يحملك على العملِ والبعدِ عن المعاصي؛ فاجعل دعاءك «ربنا اصرف عنا عذاب جهنم» من وردك، فهو من دأبِ عبادِ الرحمنِ الخائفين."}},{"n":66,"reflection":{"text":"«إنها ساءت مستقرا ومقاما» — إنّ جهنمَ قبحت مستقرًّا يُستقَرّ فيه ومقامًا يُقام فيه؛ ففي هذا ذمُّ النارِ منزلًا ومقامًا، وأنها أسوأُ مصير؛ فاحذر أن تكون النارُ مستقرَّك، واعمل لدارٍ حسنت مستقرًّا ومقامًا (الجنّة)؛ فبين المصيرين بونٌ بعيد، فآثِر دارَ النعيمِ على دارِ العذاب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من النارِ منزلًا، والعملُ لحسنِ المستقرّ."},"action":{"text":"احذر أن تكون النارُ مستقرَّك ومقامك، فبئس المنزلُ هي؛ واعمل بالطاعةِ لدارٍ حسنت مستقرًّا ومقامًا وهي الجنّة؛ فوازِن بين قبحِ منزلِ النارِ وحسنِ منزلِ الجنّة، لتؤثر دارَ النعيمِ بالإيمانِ والعمل."}},{"n":67,"reflection":{"text":"«والذين إذا أنفقوا لم يسرفوا ولم يقتروا وكان بين ذلك قواما» — والذين إذا أنفقوا لم يتجاوزوا الحدَّ إسرافًا ولم يضيّقوا بخلًا، بل كان إنفاقهم وسطًا عدلًا بين ذلك؛ ففي هذا أنّ من صفاتِ عبادِ الرحمنِ الاعتدالَ في الإنفاق، وأنّ خيرَ الأمورِ أوسطها؛ فاقتصد في إنفاقك بين الإسرافِ والبخل، فالاعتدالُ في المالِ من صفاتِ الصالحين وحفظٌ للنعمة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["لم يسرفوا ولم يقتروا وكان بين ذلك قواما"],"heart_state":{"text":"الاعتدالُ في الإنفاقِ بين الإسرافِ والبخل."},"action":{"text":"اقتصد في إنفاقك فلا تسرف فتبذّر، ولا تقتّر فتبخل، بل اجعله وسطًا عدلًا؛ فالاعتدالُ في المالِ من صفاتِ عبادِ الرحمنِ وحفظٌ للنعمة؛ فأنفق في الحقِّ بلا تبذير، وأمسك بلا بخل، فخيرُ الأمورِ أوسطها."}},{"n":68,"reflection":{"text":"«والذين لا يدعون مع الله إلها آخر ولا يقتلون النفس التي حرم الله إلا بالحق ولا يزنون ومن يفعل ذلك يلق أثاما» — والذين لا يعبدون مع الله معبودًا آخر، ولا يقتلون النفسَ التي حرّم الله قتلها إلا بحقٍّ (كقصاصٍ أو ردّة)، ولا يزنون، ومن يفعل هذه الكبائرَ يلقَ عقوبةً وإثمًا عظيمًا؛ ففي هذا أنّ من صفاتِ عبادِ الرحمنِ اجتنابَ أكبرِ الكبائر: الشركِ والقتلِ والزنا؛ فاجتنب هذه الكبائرَ الثلاثَ الموبقة، فالتوحيدُ وحفظُ الدماءِ والأعراضِ من أسسِ الدين.","source":"تفسير السعدي","grade":"ma'thur"},"names":["لا يدعون مع الله إلها آخر"],"heart_state":{"text":"اجتنابُ الكبائرِ: الشركِ والقتلِ والزنا."},"action":{"text":"اجتنب أكبرَ الكبائر: الشركَ بالله، وقتلَ النفسِ المحرَّمةِ بغيرِ حقّ، والزنا؛ فهذه موبقاتٌ تلقى بها الآثام؛ فوحّد الله، واحفظ الدماءَ والأعراض؛ فاجتنابُ الكبائرِ من صفاتِ عبادِ الرحمنِ وأساسُ استقامةِ الدين."}},{"n":69,"reflection":{"text":"«يضاعف له العذاب يوم القيامة ويخلد فيه مهانا» — يُضاعَف العذابُ لمن فعل تلك الكبائرَ يوم القيامة، ويبقى فيه ذليلًا مهانًا؛ ففي هذا تعظيمُ عقوبةِ الكبائرِ وأنها مضاعفةٌ مهينة؛ فاحذر الكبائرَ التي يُضاعَف بها العذابُ ويُخلَّد صاحبها مهانًا، وبادر بالتوبةِ منها إن وقعت، فعاقبتها الهوانُ والخلود.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكبائرِ التي يُضاعَف بها العذابُ والهوان."},"action":{"text":"احذر الكبائرَ التي يُضاعَف بها العذابُ يوم القيامةِ ويُخلَّد صاحبها في الهوان، وبادر بالتوبةِ منها إن وقعت فيها؛ فعاقبتها الذلُّ والخلودُ في العذاب؛ فاجتنبها ابتداءً، وإن زللت فارجع إلى الله سريعًا قبل الفوات."}},{"n":70,"reflection":{"text":"«إلا من تاب وآمن وعمل عملا صالحا فأولئك يبدل الله سيئاتهم حسنات وكان الله غفورا رحيما» — إلا من تاب من تلك الكبائرِ وآمن وعمل صالحًا، فأولئك يبدّل الله سيّئاتهم حسناتٍ بصدقِ توبتهم، وكان الله غفورًا رحيمًا؛ ففي هذا سعةُ رحمةِ الله بقبولِ التوبةِ وتبديلِ السيّئاتِ حسنات، وأنّ التوبةَ الصادقةَ تمحو الكبائر؛ فمهما أذنبت فبادر بالتوبةِ والإيمانِ والعملِ الصالح، فالله يبدّل سيّئاتك حسناتٍ، فلا تقنط من رحمته.","source":"تفسير السعدي","grade":"ma'thur"},"names":["يبدل الله سيئاتهم حسنات","غفورا رحيما"],"heart_state":{"text":"المبادرةُ بالتوبةِ رجاءَ تبديلِ السيّئاتِ حسنات."},"action":{"text":"مهما عظمت ذنوبك فبادر بالتوبةِ الصادقةِ والإيمانِ والعملِ الصالح، فإنّ الله يبدّل سيّئاتِ التائبين حسناتٍ برحمته؛ فلا تقنط من مغفرته مهما أسرفت؛ فالله غفورٌ رحيمٌ يقبل التوبةَ ويحوّل السيّئةَ حسنةً لمن صدق."}},{"n":71,"reflection":{"text":"«ومن تاب وعمل صالحا فإنه يتوب إلى الله متابا» — ومن تاب من ذنبه وعمل صالحًا فإنه يرجع إلى الله رجوعًا صحيحًا مقبولًا؛ ففي هذا أنّ التوبةَ الصادقةَ المقرونةَ بالعملِ الصالحِ رجوعٌ حقيقيٌّ إلى الله يُقبَل؛ فاجعل توبتك صادقةً مقرونةً بالعملِ الصالح، فتلك التوبةُ النصوحُ التي يرجع بها العبدُ إلى الله رجوعًا حقيقيًّا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحقيقُ التوبةِ الصادقةِ المقرونةِ بالعملِ الصالح."},"action":{"text":"اجعل توبتك صادقةً نصوحًا مقرونةً بالعملِ الصالح، فتلك هي التوبةُ التي يرجع بها العبدُ إلى الله رجوعًا حقيقيًّا مقبولًا؛ فلا تكتفِ بترْكِ الذنبِ بل أتبعه بالصالحاتِ التي تمحوه؛ فالتوبةُ عملٌ وقولٌ وقلبٌ لا مجردَ ندم."}}]},{"title":"تمامُ صفاتِ عبادِ الرحمنِ وجزاؤهم","range":[72,77],"theme":"اجتنابُ الزور، والتأثّرُ بالآيات، ودعاءُ الذريّةِ الصالحة، وجزاءُ الغرفة","verses":[{"n":72,"reflection":{"text":"«والذين لا يشهدون الزور وإذا مروا باللغو مروا كراما» — والذين لا يحضرون مجالسَ الباطلِ والكذبِ ولا يشهدون شهادةَ الزور، وإذا مرّوا باللغوِ والباطلِ أعرضوا عنه مكرّمين أنفسهم عن الخوضِ فيه؛ ففي هذا أنّ من صفاتِ عبادِ الرحمنِ اجتنابَ الزورِ ومجالسِ الباطل، والترفّعَ عن اللغو؛ فاجتنب شهادةَ الزورِ ومجالسَ الباطل، وأعرِض عن اللغوِ مكرّمًا نفسك، فذلك من صفاتِ عبادِ الرحمن.","source":"تفسير السعدي","grade":"ma'thur"},"names":["لا يشهدون الزور","وإذا مروا باللغو مروا كراما"],"heart_state":{"text":"اجتنابُ الزورِ ومجالسِ الباطل، والترفّعُ عن اللغو."},"action":{"text":"اجتنب شهادةَ الزورِ وحضورَ مجالسِ الباطلِ والكذب، وإذا مررت باللغوِ فأعرِض عنه مكرّمًا نفسك عن الخوضِ فيه؛ فذلك من صفاتِ عبادِ الرحمن؛ فصُن سمعك ولسانك ومجلسك عن الباطل، وارفع نفسك عن سفاسفِ القولِ والفعل."}},{"n":73,"reflection":{"text":"«والذين إذا ذكروا بآيات ربهم لم يخروا عليها صما وعميانا» — والذين إذا وُعِظوا بآياتِ ربّهم أقبلوا عليها بقلوبٍ واعيةٍ وأعينٍ مبصرة، ولم يمرّوا عليها كالصمِّ العُميِ الذين لا ينتفعون؛ ففي هذا أنّ من صفاتِ عبادِ الرحمنِ التأثّرَ بآياتِ الله والانتفاعَ بها، لا الإعراضَ عنها؛ فأقبل على آياتِ الله عند تذكيرك بها بقلبٍ حاضرٍ منتفع، ولا تمرّ عليها كالغافلِ الأصمّ، فالانتفاعُ بها صفةُ الصالحين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["لم يخروا عليها صما وعميانا"],"heart_state":{"text":"الإقبالُ على آياتِ الله والانتفاعُ بها عند التذكير."},"action":{"text":"أقبل على آياتِ الله عند سماعها وتذكيرك بها بقلبٍ واعٍ وسمعٍ مصغٍ وبصرٍ متدبّر، فتتأثّر وتنتفع؛ ولا تمرّ عليها كالأصمِّ الأعمى الغافل؛ فالتأثّرُ بآياتِ الله والانتفاعُ بها من صفاتِ عبادِ الرحمن، فاجعل لكلِّ آيةٍ أثرًا."}},{"n":74,"reflection":{"text":"«والذين يقولون ربنا هب لنا من أزواجنا وذرياتنا قرة أعين واجعلنا للمتقين إماما» — والذين يدعون: ربّنا هب لنا من أزواجنا وذريّاتنا ما تقرّ به أعيننا من صلاحهم وطاعتهم، واجعلنا قدوةً للمتّقين يُقتدى بنا في الخير؛ ففي هذا أنّ من صفاتِ عبادِ الرحمنِ الحرصَ على صلاحِ الأهلِ والذريّةِ وعلوَّ الهمّةِ بطلبِ الإمامةِ في الخير؛ فادعُ الله بصلاحِ أهلك وذريّتك، واطلب أن تكون قدوةً في الخير، فتلك همّةُ عبادِ الرحمن.","source":"تفسير السعدي","grade":"ma'thur"},"names":["هب لنا من أزواجنا وذرياتنا قرة أعين","واجعلنا للمتقين إماما"],"heart_state":{"text":"طلبُ صلاحِ الأهلِ والذريّة، وعلوُّ الهمّةِ بالإمامةِ في الخير."},"action":{"text":"ادعُ الله أن يصلح لك أزواجك وذريّتك ويجعلهم قرّةَ عينٍ لك بطاعتهم وصلاحهم، واطلب أن تكون إمامًا للمتّقين يُقتدى بك في الخير؛ فاحرص على صلاحِ بيتك وعلوِّ همّتك في الطاعة؛ فتلك دعوةُ عبادِ الرحمنِ وهمّتهم العالية."}},{"n":75,"reflection":{"text":"«أولئك يجزون الغرفة بما صبروا ويلقون فيها تحية وسلاما» — أولئك المتّصفون بتلك الصفاتِ يُجزَون المنازلَ العاليةَ في الجنّةِ بسببِ صبرهم على الطاعةِ وعن المعصية، ويُستقبَلون فيها بالتحيّةِ والسلامِ من الملائكة؛ ففي هذا أنّ جزاءَ عبادِ الرحمنِ الغرفةُ العاليةُ بصبرهم، وأنّ الصبرَ سببُ رفعةِ المنازل؛ فاتّصف بصفاتِ عبادِ الرحمنِ واصبر على الطاعة، فبالصبرِ تُنال الغرفُ العاليةُ في الجنّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["يجزون الغرفة بما صبروا"],"heart_state":{"text":"الصبرُ على الطاعةِ رجاءَ الغرفِ العالية."},"action":{"text":"اتّصف بصفاتِ عبادِ الرحمن، واصبر على الطاعةِ وعن المعصيةِ وعلى الأقدار، فبالصبرِ تُجزى الغرفةَ العاليةَ في الجنّةِ وتُستقبَل بالتحيّةِ والسلام؛ فالصبرُ سببُ رفعةِ المنازل، فوطّن نفسك عليه، فعاقبتُه أعلى الجنان."}},{"n":76,"reflection":{"text":"«خالدين فيها حسنت مستقرا ومقاما» — ماكثين في تلك الغرفِ العاليةِ أبدًا، حسنت مستقرًّا يُستقَرّ فيه ومقامًا يُقام فيه؛ ففي هذا وصفُ الجنّةِ بحسنِ المنزلِ ودوامِ نعيمها، مقابلَ قبحِ النار؛ فاعمل لدارٍ حسنت مستقرًّا ومقامًا نعيمها دائم، فبها يخلد أهلها في سرورٍ لا ينقطع، فاجعلها غايةَ سعيك.","source":"تفسير السعدي","grade":"ma'thur"},"names":["حسنت مستقرا ومقاما"],"heart_state":{"text":"العملُ للجنّةِ ذاتِ المستقرِّ الحسنِ الدائم."},"action":{"text":"اعمل بالإيمانِ والطاعةِ للجنّةِ التي حسنت مستقرًّا ومقامًا، يخلد أهلها فيها في نعيمٍ دائم؛ فوازِن بين حسنِ منزلها ودوامِ نعيمها وقبحِ النارِ وعذابها؛ فاجعل الجنّةَ غايةَ سعيك، فنعيمها لا ينقطع وسرورها لا يزول."}},{"n":77,"reflection":{"text":"«قل ما يعبأ بكم ربي لولا دعاؤكم فقد كذبتم فسوف يكون لزاما» — قل: أيُّ اكتراثٍ وعنايةٍ لربّي بكم لولا دعاؤكم وعبادتكم إياه؟ فقيمتكم عنده بدعائكم وإيمانكم، فقد كذّبتم أيها الكفارُ فسوف يكون تكذيبكم لزامًا يلزمكم عذابه؛ ففي هذا أنّ قيمةَ العبدِ عند الله بدعائه وعبادته، وأنّ التكذيبَ يلزمه العذاب؛ فاعرف أنّ شرفك وقيمتك بدعائك وعبادتك لله، فأكثر من دعائه وعبادته، فبها تعظم منزلتك عنده.","source":"تفسير السعدي","grade":"ma'thur"},"names":["ما يعبأ بكم ربي لولا دعاؤكم"],"heart_state":{"text":"معرفةُ أنّ قيمةَ العبدِ بدعائه وعبادته لله."},"action":{"text":"اعلم أنّ قيمتك وشرفك عند الله بدعائك وعبادتك وإيمانك، فلولا ذلك ما اكترث بك؛ فأكثر من دعاءِ الله وعبادته والتضرّعِ إليه، فبها تعظم منزلتك عنده وتنال رحمته؛ واحذر التكذيبَ فإنه يلزم صاحبه العذاب."}}]}],"coverage":{"covered":77,"total":77}};
